CREATE TABLE Inspector (
    Inspector_ID INTEGER PRIMARY KEY
);

CREATE TABLE Death_Record (
    Death_Record_ID INTEGER PRIMARY KEY,
    Inspector_ID INTEGER NOT NULL,
    Last_Modified_Time DATETIME,
    Name VARCHAR(255),
    Unique_ID INTEGER,
    FOREIGN KEY (Inspector_ID) REFERENCES Inspector(Inspector_ID)
);

CREATE TABLE Confirmed_Death_Record (
    Death_Record_ID INTEGER NOT NULL,
    Inspector_ID INTEGER NOT NULL,
    PRIMARY KEY (Inspector_ID, Death_Record_ID),
    FOREIGN KEY (Death_Record_ID) REFERENCES Death_Record(Death_Record_ID),
    FOREIGN KEY (Inspector_ID) REFERENCES Inspector(Inspector_ID)
);
